import{_ as a,a as t}from"./chunks/api2.Dw9IoJLQ.js";import{_ as o,o as r,c as n,a5 as i}from"./chunks/framework.DvE3tBec.js";const f=JSON.parse('{"title":"About","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1791387718000}'),s={name:"about.md"};function l(c,e,p,d,h,u){return r(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h1><p>Earth Observation data are becoming too large to be downloaded locally for analysis. Also, the way they are organised (as tiles, or <em>granules</em>: files containing the imagery for a small part of the Earth and a single observation date) makes it unnecessary complicated to analyse them. The solution to this is to store these data in the cloud, on compute back-ends, process them there, and browse the results or download resulting figures or numbers. But how do we do that?</p><p>openEO develops an open application programming interface (API) that connects clients like R, Python and JavaScript to big Earth observation cloud back-ends in a simple and unified way.</p><p>With such an API,</p><ul><li>each client can work with every back-end, and</li><li>it becomes possible to compare back-ends in terms of capacity, cost, and results (validation, reproducibility)</li></ul><h2 id="openeo" tabindex="-1">openEO? <a class="header-anchor" href="#openeo" aria-label="Permalink to &quot;openEO?&quot;">​</a></h2><p>The acronym openEO contracts two concepts:</p><ul><li><strong>open</strong>: used here in the context of open source software; open source software is available in source code form, and can be freely modified and redistributed; the openEO project will create open source software, reusable under a liberal open source license (Apache 2.0)</li><li><strong>EO</strong>: Earth observation</li></ul><p>Jointly, the openEO targets the processing and analysis of Earth observation data. The main objectives of the project are the following concepts:</p><ul><li><strong>Simplicity</strong>: nowadays, many end-users use Python or R to analyse data and JavaScript to develop web applications; analysing large amounts of EO imagery should be equally simple, and seamlessly integrate with existing workflows</li><li><strong>Unification</strong>: current EO cloud back-ends all have <a href="https://www.r-spatial.org/2016/11/29/openeo.html" target="_blank" rel="noreferrer">a different API</a>, making EO data analysis hard to validate and reproduce and back-ends difficult to compare in terms of capability and costs, or to combine them in a joint analysis across back-ends. A unified API can resolve many of these problems.</li></ul><p>The following pages introduce the core concepts of the project. Make sure to introduce yourself to the major technical terms used in the openEO project by reading the <a href="/documentation/1.0/glossary.html">glossary</a>.</p><h2 id="why-an-api" tabindex="-1">Why an API? <a class="header-anchor" href="#why-an-api" aria-label="Permalink to &quot;Why an API?&quot;">​</a></h2><p>An API is an application programming interface. It <em>defines</em> a <em>language</em> that two computers (a client and a server) use to communicate.</p><p>The following figure shows how many interfaces are needed to be able to compare back-ends from different clients, without an openEO API:</p><p><img src="'+a+'" alt="Structure before openEO"></p><p>With an openEO API (dark blue), the situation becomes much easier:</p><p><img src="'+t+'" alt="Structure with openEO"></p><p>However, existing back-ends need to be taught to work with the new API, and clients that interact with back-ends need to be developed.</p><p>The task of the openEO project is to design, develop, and evaluate an API for cloud-based Earth Observation data processing.</p><h2 id="more-information" tabindex="-1">More information <a class="header-anchor" href="#more-information" aria-label="Permalink to &quot;More information&quot;">​</a></h2><ul><li>The <a href="https://zenodo.org/record/1065474" target="_blank" rel="noreferrer">project proposal</a></li><li>A jointly written <a href="http://r-spatial.org/2016/11/29/openeo.html" target="_blank" rel="noreferrer">blog entry that motivated the openEO proposal</a></li><li>openEO publications indexed by <a href="https://explore.openaire.eu/search/advanced/research-outcomes?f0=relprojectid&amp;fv0=corda__h2020%253A%253A40125fb230a91b0fb0b156b12cd90682" target="_blank" rel="noreferrer">OpenAIRE</a> and <a href="https://www.researchgate.net/search.Search.html?type=project&amp;query=openeo" target="_blank" rel="noreferrer">ResearchGate</a></li></ul>',21)])])}const g=o(s,[["render",l]]);export{f as __pageData,g as default};
